/**
 * External dependencies
 */
import { addFilter } from '@wordpress/hooks';
function enhanceColumnBlock() {
    addFilter('blocks.registerBlockType', 'woocommerce-email-editor/change-column', (settings, name) => {
        if (name === 'core/column') {
            return {
                ...settings,
                supports: {
                    ...settings.supports,
                    background: {
                        backgroundImage: true,
                    },
                },
            };
        }
        return settings;
    });
}
export { enhanceColumnBlock };
